"""Les 26 combattants de la vague 10 (Univers n° 75 à 100).

Ajoutés au catalogue quand leurs 26 fiches sont prêtes : python3 outils/vague10/_integrer.py.
Même format que outils/vague9/_combattants.py ; « rare » : True pour un combattant Rare (110 PV, 54 Att, 4 Déf).
Spatiocommando a deux illustrations : la carte seule sert d'illustration, celle de la planche de tenue alternative.
"""

COSMODROME = ("astralis", "Le Cosmodrome d'Astralis")
ZENITH = ("astralis", "L'Observatoire du Zénith")
ACADEMIE = ("astralis", "L'Académie céleste")


def c(id, nom, style, familleStyle, specialite, famille, fiche, lieu, apparence, questions, histoire, liens,
      rare=False, domaine="Univers"):
    return dict(id=id, nom=nom, style=style, familleStyle=familleStyle, rare=rare,
                specialite=specialite, famille=famille, domaine=domaine,
                fiche=fiche, generateur=None, difficulte=2, pays=lieu[0], lieu=lieu[1],
                apparence=apparence, questions=questions, histoire=histoire, liens=liens)


AST = "Astronautes"
INS = "Instruments d'observation"
ANO = "Astronomes"

