assert len(COMBATTANTS) == 26
assert len({x["id"] for x in COMBATTANTS}) == 26
assert all(len(x["histoire"]) <= 420 for x in COMBATTANTS), [(x["id"], len(x["histoire"])) for x in COMBATTANTS if len(x["histoire"]) > 420]
